const symbols = new Map();                       // token type -> { nud, led, lbp }
symbols.set("-", { lbp: 30,                      // binding power as infix
  nud: (p, _t)     => ({ type: "neg", arg: p.expr(70) }),
  led: (p, left, _t) => ({ type: "sub", left, right: p.expr(31) }),   // left-assoc: lbp + 1
});
function expr(minBp) {
  let left = symbols.get(take().type).nud(parser, previous());      // null denotation
  while (minBp < (symbols.get(peek().type)?.lbp ?? 0)) {            // left denotation
    left = symbols.get(take().type).led(parser, left, previous());
  }
  return left;
}
